def solution():
    from pulp import LpProblem, LpVariable, LpMinimize, lpSum, LpStatus
    from itertools import combinations

    # Define the graph
    graph = {
        1: [3],
        2: [3, 4],
        3: [1, 2, 4],
        4: [2, 3, 5, 6],
        5: [4],
        6: [4]
    }

    # Define the colors
    colors = ['A', 'B', 'C']

    # Create a linear programming problem
    prob = LpProblem("Graph Coloring", LpMinimize)

    # Create variables for each vertex and color
    variables = {}
    for vertex in graph:
        for color in colors:
            variables[(vertex, color)] = LpVariable(f'v{vertex}_{color}', 0, 1, 'Binary')

    # Add constraints to ensure each vertex is assigned exactly one color
    for vertex in graph:
        prob += lpSum([variables[(vertex, color)] for color in colors]) == 1

    # Add constraints to ensure no two adjacent vertices have the same color
    for vertex in graph:
        for neighbor in graph[vertex]:
            for color in colors:
                prob += variables[(vertex, color)] + variables[(neighbor, color)] <= 1

    # Solve the problem
    prob.solve()

    # Extract the solution
    solution = {}
    for vertex in graph:
        for color in colors:
            if variables[(vertex, color)].varValue == 1:
                solution[vertex] = color

    return solution
